//! Shared verifier body, explicit source-owned canonical tree domain. Uses
//! retained child proofs; no new outer proof is generated by this gate.
const std = @import("std");
const E = @import("stwo_prover_engine");
const core = @import("stwo_core");
const Q = core.fields.qm31.QM31;
const Fold = @import("fold.zig");
const Owner = @import("../native_group/keys.zig").Owner;
const Ref = @import("execution_keys.zig").Ref;
const profile = @import("../op_profile.zig").Profile.op_target_b4_q72_p0_fold4_v1;
fn mutateAll(owner: *@import("../context.zig").Context, ports: Fold.MutationPorts) !usize {
    const ctx = owner.algebra();
    var count: usize = 0;
    for (0..2) |child| {
        for (ports.outputs[child]) |port| {
            const saved = ctx.get(port);
            ctx.value_table.items[port.idx] = saved.add(Q.one());
            const accepted = try owner.isCircuitValid();
            ctx.value_table.items[port.idx] = saved;
            try std.testing.expect(!accepted);
            count += 1;
        }
        for (ports.fixed[child]) |port| {
            const saved = ctx.get(port);
            ctx.value_table.items[port.idx] = saved.add(Q.one());
            const accepted = try owner.isCircuitValid();
            ctx.value_table.items[port.idx] = saved;
            try std.testing.expect(!accepted);
            count += 1;
        }
        for (ports.claims[child][0..ports.claim_counts[child]]) |claim| for (claim) |port| {
            const saved = ctx.get(port);
            ctx.value_table.items[port.idx] = saved.add(Q.one());
            const accepted = try owner.isCircuitValid();
            ctx.value_table.items[port.idx] = saved;
            try std.testing.expect(!accepted);
            count += 1;
        };
        const port = ports.samples[child];
        const saved = ctx.get(port);
        ctx.value_table.items[port.idx] = saved.add(Q.one());
        const accepted = try owner.isCircuitValid();
        ctx.value_table.items[port.idx] = saved;
        try std.testing.expect(!accepted);
        count += 1;
    }
    try std.testing.expect(try owner.isCircuitValid());
    return count;
}
test "R7 canonical fold host digest matches native group and keeps default domain distinct" {
    const left: Fold.Digest = @splat(Q.fromBase(core.fields.m31.M31.fromCanonical(3)));
    const right: Fold.Digest = @splat(Q.fromBase(core.fields.m31.M31.fromCanonical(7)));
    try std.testing.expectEqualDeep(try @import("../native_omul/fold.zig").digest(left, right), try Fold.canonicalDigest(left, right));
    try std.testing.expect(!std.meta.eql(try Fold.digest(left, right), try Fold.canonicalDigest(left, right)));
}
test "R7 canonical shared fold source numeric all child inputs and typed owner retirement" {
    const directory = std.posix.getenv("STWO_OP_R7_CANONICAL_CHILDREN") orelse return error.SkipZigTest;
    const budget = try E.host_budget_allocator.SharedHostBudget.create(std.heap.smp_allocator, 24 << 30);
    defer budget.destroy();
    {
        const a = budget.allocator();
        var pool: E.work_pool.WorkPool = .{};
        try pool.initInPlaceWithOptions(.{ .worker_count = 8 });
        defer pool.deinit();
        var binding = try E.work_pool.ScopedPoolBinding.init(&pool);
        defer binding.deinit();
        const Fixture = @import("recursive_test.zig");
        var c0 = try Fixture.source(a, 7, 3, false);
        defer c0.deinit();
        var c1 = try Fixture.source(a, 19, 65537, false);
        defer c1.deinit();
        const output0 = Fixture.outputs(&c0);
        const output1 = Fixture.outputs(&c1);
        var t0 = try Fixture.source(a, 7, 3, true);
        defer t0.deinit();
        var t1 = try Fixture.source(a, 19, 65537, true);
        defer t1.deinit();
        var k0 = Owner{ .r7 = try @import("outer_authority.zig").Key.init(a, &t0, profile) };
        defer k0.deinit();
        var k1 = Owner{ .r7 = try @import("outer_authority.zig").Key.init(a, &t1, profile) };
        defer k1.deinit();
        const identities = [2][32]u8{ k0.ref().identity(), k1.ref().identity() };
        k0.retireProverData();
        k0.retireProverData();
        k1.retireProverData();
        try std.testing.expectEqualDeep(identities[0], k0.ref().identity());
        try std.testing.expectEqualDeep(identities[1], k1.ref().identity());
        var dir = try std.fs.cwd().openDir(directory, .{});
        defer dir.close();
        const b0 = try dir.readFileAlloc(a, "child0.bin", 2 << 20);
        defer a.free(b0);
        const b1 = try dir.readFileAlloc(a, "child1.bin", 2 << 20);
        defer a.free(b1);
        var p0 = try k0.verifyCaptured(a, &output0, b0);
        defer p0.deinit(a);
        var p1 = try k1.verifyCaptured(a, &output1, b1);
        defer p1.deinit(a);
        const pair = Fold.Source{ .children = .{ .{ .key = k0.ref(), .verified = p0.borrow(), .output = output0 }, .{ .key = k1.ref(), .verified = p1.borrow(), .output = output1 } } };
        const expected = try pair.expectedCanonicalOutput();
        try std.testing.expectEqualDeep(try @import("../native_omul/fold.zig").digest(output0, output1), expected);
        var ports: Fold.MutationPorts = undefined;
        var canonical = try pair.buildCanonicalTreeWithPortsForTest(a, &ports);
        defer canonical.deinit();
        try std.testing.expect(try canonical.isCircuitValid());
        try std.testing.expectEqual(@as(usize, 70), try mutateAll(&canonical, ports));
        var trace = try (Fold.TraceSource{ .keys = .{ k0.ref(), k1.ref() } }).buildCanonicalTree(a);
        defer trace.deinit();
        try std.testing.expectEqualDeep(try trace.rawCountsForNativeDot(), try canonical.rawCountsForNativeDot());
        var owner = try Owner.canonicalFold(a, .{ k0.ref(), k1.ref() }, profile);
        defer owner.deinit();
        var numerical = try @import("outer_authority.zig").Key.init(a, &canonical, profile);
        defer numerical.deinit();
        try std.testing.expectEqualDeep(owner.ref().identity(), numerical.core.base.identity);
        owner.retireProverData();
        try std.testing.expectEqualDeep(owner.ref().identity(), numerical.core.base.identity);
        // The default R7 parent proof and independently derived source key must
        // remain usable; new canonical tags do not replace its existing domain.
        var legacy = try (Fold.TraceSource{ .keys = .{ k0.ref(), k1.ref() } }).build(a);
        defer legacy.deinit();
        var legacy_key = Owner{ .r7 = try @import("outer_authority.zig").Key.init(a, &legacy, profile) };
        defer legacy_key.deinit();
        try std.testing.expectEqualStrings("0cc52cbfefe753b04f15c9ce4462b498bf61e4d6fed79476aa500486d72b281c", &std.fmt.bytesToHex(legacy_key.ref().identity(), .lower));
        legacy_key.retireProverData();
        const old = try dir.readFileAlloc(a, "parent.bin", 2 << 20);
        defer a.free(old);
        const old_output = try pair.expectedOutput();
        try legacy_key.verify(a, &old_output, old);
        try std.testing.expect(!std.meta.eql(old_output, expected));
        std.debug.print("OP_R7_CANONICAL_FOLD numerical=true source=true input_mutations=70 typed_owner_retirement=true retained_default_parent=true new_proof=false\n", .{});
    }
    try std.testing.expectEqual(@as(usize, 0), budget.snapshot().live_bytes);
    try std.testing.expectEqual(@as(usize, 0), budget.snapshot().external_live_bytes);
}
